/** Genuine 081+083+084 composition. Optional missing production authority is never replaced by caller evidence. */
public final class FormalAgentAcceptanceEvidence implements PublicationEvidenceRevalidation {
 private final EnterpriseAccess access;private final EvaluationService evaluations;private final EvaluationSchema evaluation;private final FormalAgentPublicationSchema schema;private final PermissionSchema json;private final FormalAgentCandidateAuthority candidates;private final EvaluationAcceptancePolicyService policies;private final ExpertQualificationAuthority experts;private final ExpertQualificationStore expertStore;private final ObjectProvider<FormalEvaluationExecutionEvidence> executions;private final EvaluationAcceptanceStatisticsEngine statistics;private final EvaluationRuleAuthority rules;private final EvaluationReferences references;private final AgentPublicationDependencies dependencies;
 public FormalAgentAcceptanceEvidence(EnterpriseAccess access,EvaluationService evaluations,EvaluationSchema evaluation,FormalAgentPublicationSchema schema,PermissionSchema json,FormalAgentCandidateAuthority candidates,EvaluationAcceptancePolicyService policies,ExpertQualificationAuthority experts,ExpertQualificationStore expertStore,ObjectProvider<FormalEvaluationExecutionEvidence> executions,EvaluationAcceptanceStatisticsEngine statistics,EvaluationRuleAuthority rules,EvaluationReferences references,AgentPublicationDependencies dependencies){this.rules=rules;this.references=references;this.dependencies=dependencies;this.access=access;this.evaluations=evaluations;this.evaluation=evaluation;this.schema=schema;this.json=json;this.candidates=candidates;this.policies=policies;this.experts=experts;this.expertStore=expertStore;this.executions=executions;this.statistics=statistics;}
 public static final class Prepared implements PublicationEvidenceRevalidation.Prepared {
  private final FormalAgentAcceptanceEvidence owner;private final String actor,context,specification;private final boolean historical;private final EvaluationAcceptancePolicyService.PreparedPolicy policy;private final Map<PermissionProtocol.Basis,PermissionProtocol.Basis> executionPolicies;private final Map<PermissionProtocol.Basis,FormalEvaluationExecutionEvidence.Prepared> execution;
  private Prepared(FormalAgentAcceptanceEvidence owner,String actor,String context,String specification,boolean historical,EvaluationAcceptancePolicyService.PreparedPolicy policy,Map<PermissionProtocol.Basis,PermissionProtocol.Basis> executionPolicies,Map<PermissionProtocol.Basis,FormalEvaluationExecutionEvidence.Prepared> execution){this.owner=owner;this.actor=actor;this.context=context;this.specification=specification;this.historical=historical;this.policy=policy;this.executionPolicies=Map.copyOf(executionPolicies);this.execution=Map.copyOf(execution);}
 }
 @Override public Prepared prepare(ApplicationSessionIdentity.Verified subject,String context,JsonNode content,boolean historical)throws Exception {
  var original=specification(content);String canonical=schema.canonical(original);var eval=basis(original.required("evaluation"));var policy=basis(original.required("statistics_policy"));
  var bindings=access.execute(subject,a->checked(()->{current(a,context);var snapshot=evaluations.requireFormalDefinitionMetadata(a,eval.version_id());if(!eval.content_sha256().equals(snapshot.row().contentHash()))bad();var map=new LinkedHashMap<PermissionProtocol.Basis,PermissionProtocol.Basis>();for(var candidate:snapshot.definition().request().candidates()){var identity=candidates.require(a,candidate,snapshot.row().projectId(),"EVALUATION_RESULTS");map.put(candidate,identity.executionPolicy());}if(!map.containsKey(basis(original.required("candidate"))))bad();return map;}));
  var approved=historical?policies.prepareHistorical(subject,context,policy.version_id(),policy.content_sha256()):policies.prepare(subject,context,policy.version_id(),policy.content_sha256());var runtime=execution();var completed=new LinkedHashMap<PermissionProtocol.Basis,FormalEvaluationExecutionEvidence.Prepared>();for(var entry:bindings.entrySet())completed.put(entry.getKey(),historical?runtime.prepareHistorical(subject,context,eval.version_id(),entry.getKey(),entry.getValue()):runtime.prepare(subject,context,eval.version_id(),entry.getKey(),entry.getValue()));
  return new Prepared(this,subject.user().user_id(),context,canonical,historical,approved,bindings,completed);
 }
 public Prepared prepareScoreBinding(ApplicationSessionIdentity.Verified subject,String context,JsonNode outer)throws Exception{return prepareScoreBinding(subject,context,outer,false);}
 public Prepared prepareScoreBindingRead(ApplicationSessionIdentity.Verified subject,String context,JsonNode outer)throws Exception{return prepareScoreBinding(subject,context,outer,true);}
 private Prepared prepareScoreBinding(ApplicationSessionIdentity.Verified subject,String context,JsonNode outer,boolean historical)throws Exception{
  new FormalEvaluationScoreBindingSchema(schema).validate(outer);var candidate=access.execute(subject,a->checked(()->{current(a,context);var metadata=evaluations.requireFormalDefinitionMetadata(a,outer.required("evaluation").required("version_id").asText());if(!metadata.row().contentHash().equals(outer.required("evaluation").required("content_sha256").asText()))bad();return metadata.definition().request().candidates().get(0);}));var spec=json.object();spec.set("candidate",json.tree(candidate));spec.set("evaluation",outer.required("evaluation").deepCopy());spec.set("statistics_policy",outer.required("statistics_policy").deepCopy());spec.putArray("score_bindings");return prepare(subject,context,spec,historical);
 }
 public ScoreBindingPermit requireScoreBinding(EnterpriseAccess.Admission a,JsonNode outer,Prepared prepared)throws Exception{return scoreBinding(a,outer,prepared,false);}
 public ScoreBindingRead requireScoreBindingRead(EnterpriseAccess.Admission a,JsonNode outer,Prepared prepared)throws Exception{return new ScoreBindingRead(scoreBinding(a,outer,prepared,true));}
 private ScoreBindingPermit scoreBinding(EnterpriseAccess.Admission a,JsonNode outer,Prepared prepared,boolean historical)throws Exception{
  new FormalEvaluationScoreBindingSchema(schema).validate(outer);if(prepared==null||prepared.owner!=this||prepared.historical!=historical||!a.actorId().equals(prepared.actor))deny();current(a,prepared.context);var spec=schema.read(prepared.specification);for(String field:List.of("evaluation","statistics_policy"))if(!schema.canonical(spec.required(field)).equals(schema.canonical(outer.required(field))))bad();
  var eval=basis(spec.required("evaluation"));var policy=basis(spec.required("statistics_policy"));var metadata=evaluations.requireFormalDefinitionMetadata(a,eval.version_id());if(!eval.content_sha256().equals(metadata.row().contentHash()))bad();var approved=policyView(a,policy,prepared,historical);approved.requireConsumer(a,metadata.definition());var runtimes=new HashMap<String,RuntimeView>();var witnesses=json.object();
  for(var ref:metadata.definition().request().candidates()){var identity=candidates.require(a,ref,metadata.row().projectId(),"EVALUATION_RESULTS");if(!identity.executionPolicy().equals(prepared.executionPolicies.get(ref)))bad();var runtime=runtimeView(a,eval.version_id(),ref,identity.executionPolicy(),prepared.execution.get(ref),historical);runtime.requireConsumer(a,eval.version_id(),ref,identity.executionPolicy());runtimes.put(ref.version_id(),runtime);witnesses.set(ref.version_id(),runtime.authorizations());}
  var read=new ReadPermit(this,a,metadata.definition(),approved,runtimes,historical);var snapshot=evaluations.requireFormalAcceptance(a,eval.version_id(),read);var score=snapshot.scores().stream().filter(x->x.score_id().equals(outer.required("binding").required("score_id").asText())).toList();if(score.size()!=1||!approved.expertDomain(score.get(0).observation().cell().dimension()).equals(outer.required("binding").required("domain").asText()))bad();var witness=json.object().put("schema_version","1.0.0").put("request_body_sha256",schema.hash(outer)).put("definition_sha256",eval.content_sha256());witness.set("request",outer.deepCopy());witness.set("statistics_policy",outer.required("statistics_policy").deepCopy());witness.set("policy_authorizations",approved.authorizations());witness.set("execution_authorizations",witnesses);return new ScoreBindingPermit(this,a,outer,snapshot,witness,maxClassification(snapshot.row().classification(),approved.classification()),historical);
 }
 public static final class ScoreBindingPermit {
  private final FormalAgentAcceptanceEvidence owner;private final EnterpriseAccess.Admission admission;private final JsonNode outer,witness;private final EvaluationService.AcceptanceSnapshot snapshot;private final String classification;private final boolean historical;
  private ScoreBindingPermit(FormalAgentAcceptanceEvidence owner,EnterpriseAccess.Admission a,JsonNode outer,EvaluationService.AcceptanceSnapshot snapshot,JsonNode witness,String classification,boolean historical){this.owner=owner;this.historical=historical;admission=a;this.outer=outer.deepCopy();this.snapshot=snapshot;this.witness=witness.deepCopy();this.classification=classification;}
  public EvaluationService.AcceptanceSnapshot requireConsumer(EnterpriseAccess.Admission a,JsonNode binding)throws Exception{if(historical||a!=admission||!owner.schema.canonical(binding).equals(owner.schema.canonical(outer.required("binding"))))deny();snapshot.requireConsumer(a,outer.required("evaluation").required("version_id").asText());return snapshot;}
  public JsonNode witness(){return witness.deepCopy();}public String classification(){return classification;}
 }
 public static final class ScoreBindingRead {
  private final ScoreBindingPermit proof;private ScoreBindingRead(ScoreBindingPermit proof){this.proof=proof;}
  public EvaluationService.AcceptanceSnapshot requireConsumer(EnterpriseAccess.Admission a,JsonNode binding)throws Exception{if(!proof.historical||a!=proof.admission||!proof.owner.schema.canonical(binding).equals(proof.owner.schema.canonical(proof.outer.required("binding"))))deny();proof.snapshot.requireConsumer(a,proof.outer.required("evaluation").required("version_id").asText());return proof.snapshot;}
 }
 public Verified require(EnterpriseAccess.Admission a,JsonNode request,Prepared prepared)throws Exception{if(prepared==null||prepared.historical)deny();return evaluate(a,request,prepared,false);}
 private Verified evaluate(EnterpriseAccess.Admission a,JsonNode request,Prepared prepared,boolean historical)throws Exception{
  if(prepared==null||prepared.owner!=this||prepared.historical!=historical||!a.actorId().equals(prepared.actor))deny();current(a,prepared.context);var spec=specification(request);if(!schema.canonical(spec).equals(prepared.specification))bad();var eval=basis(spec.required("evaluation"));var policy=basis(spec.required("statistics_policy"));var candidate=basis(spec.required("candidate"));
  var metadata=evaluations.requireFormalDefinitionMetadata(a,eval.version_id());if(!eval.content_sha256().equals(metadata.row().contentHash())||!"COMPLETED".equals(metadata.row().status())||!"PRODUCTION".equals(metadata.definition().request().environment())||metadata.definition().request().samples().isEmpty()||metadata.definition().request().samples().stream().anyMatch(s->!"REAL".equals(s.evidence_class())))bad();
  var approved=policyView(a,policy,prepared,historical);approved.requireConsumer(a,metadata.definition());
  var actual=new ArrayList<FormalEvaluationExecutionProtocol.Record>();var runtimeProofs=new ArrayList<RuntimeView>();var runtimeByCandidate=new HashMap<String,RuntimeView>();var authors=new HashMap<String,String>();var authorization=json.object();authorization.set("statistics_policy",approved.authorizations());var runtimeAuth=authorization.putArray("executions");
  for(var ref:metadata.definition().request().candidates()){var identity=candidates.require(a,ref,metadata.row().projectId(),"EVALUATION_RESULTS");authors.put(ref.version_id(),identity.createdBy());if(!identity.executionPolicy().equals(prepared.executionPolicies.get(ref)))bad();var runtime=runtimeView(a,eval.version_id(),ref,identity.executionPolicy(),prepared.execution.get(ref),historical);runtime.requireConsumer(a,eval.version_id(),ref,identity.executionPolicy());runtimeProofs.add(runtime);runtimeByCandidate.put(ref.version_id(),runtime);actual.addAll(runtime.records());runtimeAuth.add(runtime.authorizations());}
  var permit=new ReadPermit(this,a,metadata.definition(),approved,runtimeByCandidate,historical);var snapshot=evaluations.requireFormalAcceptance(a,eval.version_id(),permit);
  var computed=statistics.compute(snapshot.definition(),snapshot.result(),snapshot.scores(),approved.policy());if(!"PASS".equals(computed.verdict()))throw new TenantAccessException(ErrorCode.SOURCE_NOT_READY);
  var effective=new EvaluationVerdict(evaluation).effective(snapshot.definition(),snapshot.row().contentHash(),snapshot.scores());var byId=new HashMap<String,EvaluationProtocol.Score>();for(var score:effective.values())byId.put(score.score_id(),score);
  String classification=maxClassification(snapshot.row().classification(),approved.classification());var qualified=json.object().putArray("scores");var seen=new HashSet<String>();var expertProofs=new ArrayList<ExpertQualificationAuthority.VerifiedQualifiedScore>();var expertAuth=authorization.putArray("experts");
  for(var requested:spec.required("score_bindings")){var proof=experts.requireQualifiedScore(a,basis(requested),snapshot);var score=proof.score();proof.requireConsumer(a,eval.version_id(),score.score_id());if(!seen.add(score.score_id())||!score.equals(byId.get(score.score_id()))||score.scorer_id().equals(authors.get(score.observation().cell().agent_version_id())))bad();
   var cell=score.observation().cell();if(!approved.expertDomain(cell.dimension()).equals(proof.qualification().domain()))bad();var matching=actual.stream().filter(r->r.node().cell().candidate().version_id().equals(cell.agent_version_id())&&r.node().cell().sampleId().equals(cell.sample_id())&&r.node().cell().repeatIndex()==cell.repeat_index()).toList();if(matching.isEmpty()||matching.stream().anyMatch(r->!r.node().cell().input().equals(score.observation().input_ref())))bad();
   var output=score.observation().output_ref();var cellRuntime=runtimeByCandidate.get(cell.agent_version_id());if(cellRuntime==null)bad();cellRuntime.requireProfessionalOutput(cell,output);if(matching.stream().flatMap(r->r.actualArtifacts().stream()).noneMatch(o->o.artifactId().equals(output.version_id())&&o.sha256().equals(output.content_sha256())))bad();
   var allowed=new HashMap<String,String>();for(var record:matching){allow(allowed,record.node().cell().input());allow(allowed,record.node().cell().expected());for(var artifact:record.actualArtifacts())allow(allowed,new PermissionProtocol.Basis(artifact.artifactId(),artifact.sha256()));for(var artifact:List.of(record.inputManifest(),record.stepEnvelope(),record.stepResult(),record.sessionExport()))allow(allowed,new PermissionProtocol.Basis(artifact.artifactId(),artifact.sha256()));for(var invocation:record.invocations()){allow(allowed,new PermissionProtocol.Basis(invocation.modelResult().artifactId(),invocation.modelResult().sha256()));allow(allowed,new PermissionProtocol.Basis(invocation.providerCapture().artifactId(),invocation.providerCapture().sha256()));}}
   if(score.observation().evidence_refs().isEmpty())bad();for(var ref:score.observation().evidence_refs())if(!ref.content_sha256().equals(allowed.get(ref.version_id())))bad();
   var q=qualified.addObject().put("score_id",score.score_id()).put("score_sha256",evaluation.hash(score));q.set("binding",json.tree(proof.binding()));q.set("qualification",json.tree(proof.qualification().qualification()));q.set("approval",json.tree(proof.qualification().approval()));expertAuth.add(proof.qualification().authorizations());expertProofs.add(proof);classification=maxClassification(classification,expertStore.read(a,proof.binding().version_id()).classification(),expertStore.read(a,proof.qualification().qualification().version_id()).classification(),expertStore.read(a,proof.qualification().approval().version_id()).classification());
  }
  if(!seen.equals(byId.keySet()))bad();var sorted=new ArrayList<JsonNode>();qualified.forEach(sorted::add);sorted.sort(Comparator.comparing(x->x.required("score_id").asText()));qualified.removeAll();sorted.forEach(qualified::add);
  var identity=candidates.require(a,candidate,snapshot.row().projectId(),"EVALUATION_RESULTS");if(!schema.hash(identity.runtimeManifest()).equals(approved.policy().runtime_manifest_sha256())||!schema.hash(identity.manifestDefinition().required("release_scope")).equals(approved.policy().scope_sha256()))bad();
  classification=maxClassification(classification,identity.classification());var allowedClasses=new HashSet<String>();identity.manifestDefinition().required("release_scope").required("allowed_classifications").forEach(x->allowedClasses.add(x.asText()));if(!allowedClasses.contains(classification))bad();
  actual.sort(Comparator.comparing((FormalEvaluationExecutionProtocol.Record r)->r.node().cell().candidate().version_id()).thenComparing(r->r.node().cell().sampleId()).thenComparingInt(r->r.node().cell().repeatIndex()).thenComparing(r->r.node().nodeKind()));
  snapshot.requireUnchanged();approved.requireUnchanged();for(var p:runtimeProofs)p.requireUnchanged();for(var p:expertProofs)p.requireUnchanged();identity.requireUnchanged();
  return new Verified(this,a,request.deepCopy(),prepared,snapshot,identity,computed,qualified,schema.hash(actual),authorization,classification);
 }
 @Override public void requireCurrent(EnterpriseAccess.Admission a,JsonNode exact,boolean historical,PublicationEvidenceRevalidation.Prepared prepared)throws Exception{
  if(!(prepared instanceof Prepared))deny();var verified=evaluate(a,exact,(Prepared)prepared,historical);if(!verified.resultHash().equals(exact.required("result_sha256").asText())||!verified.scoreHistoryHash().equals(exact.required("score_history_sha256").asText())||!verified.statisticsHash().equals(exact.required("statistics_sha256").asText())||!verified.executionHash().equals(exact.required("execution_evidence_sha256").asText())||!verified.classification().equals(exact.required("classification").asText())||!schema.canonical(verified.qualifiedScores()).equals(schema.canonical(exact.required("qualified_scores"))))bad();
 }
 public static final class Verified {
  private final FormalAgentAcceptanceEvidence owner;private final EnterpriseAccess.Admission admission;private final JsonNode request;private final Prepared prepared;private final EvaluationService.AcceptanceSnapshot snapshot;private final FormalAgentCandidateAuthority.VerifiedCandidateIdentity candidate;private final EvaluationAcceptanceStatisticsProtocol.Result statistics;private final JsonNode qualified,auth;private final String runtimeHash,classification;
  private Verified(FormalAgentAcceptanceEvidence owner,EnterpriseAccess.Admission a,JsonNode request,Prepared prepared,EvaluationService.AcceptanceSnapshot snapshot,FormalAgentCandidateAuthority.VerifiedCandidateIdentity candidate,EvaluationAcceptanceStatisticsProtocol.Result statistics,JsonNode qualified,String runtimeHash,JsonNode auth,String classification){this.owner=owner;admission=a;this.request=request;this.prepared=prepared;this.snapshot=snapshot;this.candidate=candidate;this.statistics=statistics;this.qualified=qualified.deepCopy();this.runtimeHash=runtimeHash;this.auth=auth.deepCopy();this.classification=classification;}
  public String classification(){return classification;}
  public EvaluationService.AcceptanceSnapshot evaluation(){return snapshot;}public FormalAgentCandidateAuthority.VerifiedCandidateIdentity candidate(){return candidate;}public JsonNode qualifiedScores(){return qualified.deepCopy();}public JsonNode authorizations(){return auth.deepCopy();}public String executionHash(){return runtimeHash;}public String resultHash(){return snapshot.row().resultHash();}public String scoreHistoryHash()throws Exception{return owner.schema.hash(snapshot.scores());}public String statisticsHash()throws Exception{return owner.schema.hash(statistics);}
  public void requireConsumer(EnterpriseAccess.Admission a)throws Exception{if(a!=admission||prepared.historical)deny();requireUnchanged();}
  public void requireUnchanged()throws Exception{var current=owner.evaluate(admission,request,prepared,prepared.historical);if(!executionHash().equals(current.executionHash())||!resultHash().equals(current.resultHash())||!scoreHistoryHash().equals(current.scoreHistoryHash())||!statisticsHash().equals(current.statisticsHash())||!owner.schema.canonical(qualified).equals(owner.schema.canonical(current.qualified)))bad();}
 }
 /** Private assembler permit; construction is restricted to genuine policy and execution proofs above. */
 public static final class ReadPermit {
  private final FormalAgentAcceptanceEvidence owner;private final EnterpriseAccess.Admission admission;private final EvaluationProtocol.Definition definition;private final PolicyView policy;private final Map<String,RuntimeView> runtimes;private final boolean historical;private final TenantScope scope;
  private ReadPermit(FormalAgentAcceptanceEvidence owner,EnterpriseAccess.Admission a,EvaluationProtocol.Definition definition,PolicyView policy,Map<String,RuntimeView> runtimes,boolean historical){this.owner=owner;this.admission=a;this.definition=definition;this.policy=policy;this.runtimes=Map.copyOf(runtimes);this.historical=historical;scope=TenantScope.requireCurrent();}
  public RuleVersionProtocol.Validated require(EnterpriseAccess.Admission a,EvaluationProtocol.Definition d,List<EvaluationProtocol.Score> scores)throws java.io.IOException{
   try{if(a!=admission||scope!=TenantScope.requireCurrent()||!owner.schema.canonical(definition).equals(owner.schema.canonical(d)))deny();policy.requireConsumer(a,d);policy.requireUnchanged();
    var request=d.request();for(var candidate:request.candidates()){var runtime=runtimes.get(candidate.version_id());if(runtime==null)bad();runtime.requireUnchanged();}
    // This original independent evidence root is not silently replaced by the approved sampling policy.
    owner.references.artifact(request.project_id(),request.authorized_use_evidence());owner.dependencies.requireByUse(a,request.project_id(),List.of(new AgentPublicationDependencies.DependencyUse(request.authorized_use_evidence(),"EVALUATION_RESULTS")));
    for(var score:scores){var cell=score.observation().cell();var runtime=runtimes.get(cell.agent_version_id());if(runtime==null)bad();var matching=runtime.records().stream().filter(r->r.node().cell().candidate().version_id().equals(cell.agent_version_id())&&r.node().cell().sampleId().equals(cell.sample_id())&&r.node().cell().repeatIndex()==cell.repeat_index()).toList();if(matching.isEmpty()||matching.stream().anyMatch(r->!r.node().cell().input().equals(score.observation().input_ref())))bad();
     var allowed=new HashMap<String,String>();for(var r:matching){allow(allowed,r.node().cell().input());allow(allowed,r.node().cell().expected());for(var artifact:r.actualArtifacts())allow(allowed,new PermissionProtocol.Basis(artifact.artifactId(),artifact.sha256()));for(var artifact:List.of(r.inputManifest(),r.stepEnvelope(),r.stepResult(),r.sessionExport()))allow(allowed,new PermissionProtocol.Basis(artifact.artifactId(),artifact.sha256()));for(var invocation:r.invocations()){allow(allowed,new PermissionProtocol.Basis(invocation.modelResult().artifactId(),invocation.modelResult().sha256()));allow(allowed,new PermissionProtocol.Basis(invocation.providerCapture().artifactId(),invocation.providerCapture().sha256()));}}
     var refs=new ArrayList<>(score.observation().evidence_refs());refs.add(score.observation().input_ref());if(score.observation().output_ref()!=null){refs.add(score.observation().output_ref());runtime.requireProfessionalOutput(cell,score.observation().output_ref());}for(var ref:refs){if(!ref.content_sha256().equals(allowed.get(ref.version_id())))bad();owner.references.artifact(request.project_id(),ref);}
    }
    return owner.rules.require(a,request.rule_revision(),!historical);
   }catch(java.io.IOException e){throw e;}catch(RuntimeException e){throw e;}catch(Exception e){throw new java.io.IOException("FORMAL_EVALUATION_PROOF_UNAVAILABLE",e);}
  }
 }
 private interface PolicyView {
  EvaluationAcceptanceStatisticsProtocol.Policy policy();String expertDomain(String dimension);String classification();JsonNode authorizations();void requireConsumer(EnterpriseAccess.Admission a,EvaluationProtocol.Definition d)throws Exception;void requireUnchanged()throws Exception;
 }
 private PolicyView policyView(EnterpriseAccess.Admission a,PermissionProtocol.Basis policy,Prepared prepared,boolean historical)throws Exception{
  if(historical){var p=policies.requireHistorical(a,policy.version_id(),policy.content_sha256(),prepared.policy);return new PolicyView(){public EvaluationAcceptanceStatisticsProtocol.Policy policy(){return p.policy();}public String expertDomain(String d){return p.expertDomain(d);}public String classification(){return p.classification();}public JsonNode authorizations(){return p.authorizations();}public void requireConsumer(EnterpriseAccess.Admission a,EvaluationProtocol.Definition d)throws Exception{p.requireConsumer(a,d);}public void requireUnchanged()throws Exception{p.requireUnchanged();}};}
  var p=policies.require(a,policy.version_id(),policy.content_sha256(),prepared.policy);return new PolicyView(){public EvaluationAcceptanceStatisticsProtocol.Policy policy(){return p.policy();}public String expertDomain(String d){return p.expertDomain(d);}public String classification(){return p.classification();}public JsonNode authorizations(){return p.authorizations();}public void requireConsumer(EnterpriseAccess.Admission a,EvaluationProtocol.Definition d)throws Exception{p.requireConsumer(a,d);}public void requireUnchanged()throws Exception{p.requireUnchanged();}};
 }
 private interface RuntimeView {
  List<FormalEvaluationExecutionProtocol.Record> records();JsonNode authorizations();void requireConsumer(EnterpriseAccess.Admission a,String evaluation,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy)throws Exception;void requireProfessionalOutput(EvaluationProtocol.Cell cell,PermissionProtocol.Basis output)throws Exception;void requireUnchanged()throws Exception;
 }
 private RuntimeView runtimeView(EnterpriseAccess.Admission a,String evaluation,PermissionProtocol.Basis candidate,PermissionProtocol.Basis policy,FormalEvaluationExecutionEvidence.Prepared prepared,boolean historical)throws Exception{
  if(historical){var p=execution().requireHistorical(a,evaluation,candidate,policy,prepared);return new RuntimeView(){public List<FormalEvaluationExecutionProtocol.Record> records(){return p.records();}public JsonNode authorizations(){return p.authorizations();}public void requireConsumer(EnterpriseAccess.Admission a,String e,PermissionProtocol.Basis c,PermissionProtocol.Basis p0)throws Exception{p.requireConsumer(a,e,c,p0);}public void requireProfessionalOutput(EvaluationProtocol.Cell c,PermissionProtocol.Basis o)throws Exception{p.requireProfessionalOutput(c,o);}public void requireUnchanged()throws Exception{p.requireUnchanged();}};}
  var p=execution().require(a,evaluation,candidate,policy,prepared);return new RuntimeView(){public List<FormalEvaluationExecutionProtocol.Record> records(){return p.records();}public JsonNode authorizations(){return p.authorizations();}public void requireConsumer(EnterpriseAccess.Admission a,String e,PermissionProtocol.Basis c,PermissionProtocol.Basis p0)throws Exception{p.requireConsumer(a,e,c,p0);}public void requireProfessionalOutput(EvaluationProtocol.Cell c,PermissionProtocol.Basis o)throws Exception{p.requireProfessionalOutput(c,o);}public void requireUnchanged()throws Exception{p.requireUnchanged();}};
 }
 static String maxClassification(String...values){var levels=List.of("PUBLIC","INTERNAL","RESTRICTED","PERSONAL_HEALTH");int max=0;for(String value:values){int i=levels.indexOf(value);if(i<0)bad();max=Math.max(max,i);}return levels.get(max);}
 private static void allow(Map<String,String> refs,PermissionProtocol.Basis basis){String old=refs.putIfAbsent(basis.version_id(),basis.content_sha256());if(old!=null&&!old.equals(basis.content_sha256()))bad();}
 private JsonNode specification(JsonNode source){var n=json.object();for(String key:List.of("candidate","evaluation","statistics_policy"))n.set(key,source.required(key).deepCopy());if(source.has("score_bindings"))n.set("score_bindings",source.required("score_bindings").deepCopy());else{var bindings=n.putArray("score_bindings");for(var score:source.required("qualified_scores"))bindings.add(score.required("binding").deepCopy());}return n;}
 private FormalEvaluationExecutionEvidence execution(){var value=executions.getIfAvailable();if(value==null)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);return value;}
 private static PermissionProtocol.Basis basis(JsonNode value){return FormalAgentCandidateDependencies.basis(value);}private static void current(EnterpriseAccess.Admission a,String context){if(!a.context().context_revision().equals(context))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}
 private static <T>T checked(ThrowingSupplier<T> fn){return fn.get();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
